import{_ as e,o as t,c as r,a2 as s}from"./chunks/framework.D8Tso2Ul.js";const g=JSON.parse('{"title":"Fases de obra","description":"","frontmatter":{},"headers":[],"relativePath":"ds44/fases-obra.md","filePath":"ds44/fases-obra.md"}'),o={name:"ds44/fases-obra.md"};function n(i,a,c,d,l,p){return t(),r("div",null,[...a[0]||(a[0]=[s(`<h1 id="fases-de-obra" tabindex="-1">Fases de obra <a class="header-anchor" href="#fases-de-obra" aria-label="Permalink to &quot;Fases de obra&quot;">​</a></h1><p>En la plataforma, una obra avanza en <strong>dos dimensiones</strong> que conviene no confundir:</p><ol><li><strong>Etapa física</strong> de construcción — el avance real de lo que se está construyendo.</li><li><strong>Ciclo de gestión preventiva</strong> — cómo se gestiona la seguridad, según el DS 44.</li></ol><h2 id="etapas-fisicas" tabindex="-1">Etapas físicas <a class="header-anchor" href="#etapas-fisicas" aria-label="Permalink to &quot;Etapas físicas&quot;">​</a></h2><p>La obra pasa por cuatro etapas físicas, en orden:</p><table tabindex="0"><thead><tr><th>Etapa</th><th>¿Qué ocurre?</th></tr></thead><tbody><tr><td><strong>Excavación</strong></td><td>Movimiento de tierras, fundaciones, inicio de faena.</td></tr><tr><td><strong>Obra gruesa</strong></td><td>Estructura, hormigón, albañilería.</td></tr><tr><td><strong>Terminaciones</strong></td><td>Instalaciones, revestimientos, acabados.</td></tr><tr><td><strong>Entrega</strong></td><td>Cierre, recepción y entrega de la obra.</td></tr></tbody></table><p>Cada etapa tiene asociado un conjunto de <strong>documentos obligatorios</strong> que la plataforma prepara automáticamente al crear la obra.</p><h2 id="avance-de-etapa-con-verificacion" tabindex="-1">Avance de etapa con verificación <a class="header-anchor" href="#avance-de-etapa-con-verificacion" aria-label="Permalink to &quot;Avance de etapa con verificación&quot;">​</a></h2><p>Antes de avanzar de una etapa a la siguiente, la plataforma <strong>verifica que los documentos obligatorios de la etapa actual estén firmados</strong>. Esto evita avanzar dejando vacíos de cumplimiento.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────┐   verifica    ┌──────────────┐   verifica    ┌────────────────┐</span></span>
<span class="line"><span>│  Excavación  │ ───────────▶ │  Obra gruesa │ ───────────▶ │  Terminaciones │ ──▶ Entrega</span></span>
<span class="line"><span>└──────────────┘  docs OK ✓   └──────────────┘  docs OK ✓   └────────────────┘</span></span></code></pre></div><h2 id="el-ciclo-de-mejora-continua-planificar–hacer–verificar–actuar" tabindex="-1">El ciclo de mejora continua (Planificar–Hacer–Verificar–Actuar) <a class="header-anchor" href="#el-ciclo-de-mejora-continua-planificar–hacer–verificar–actuar" aria-label="Permalink to &quot;El ciclo de mejora continua (Planificar–Hacer–Verificar–Actuar)&quot;">​</a></h2><p>Además de la etapa física, el DS 44 exige un <strong>ciclo continuo de mejora</strong>. La plataforma lo organiza en cuatro fases que verás en la pestaña <strong>DS44 — Cumplimiento</strong> de cada obra:</p><table tabindex="0"><thead><tr><th>Fase</th><th>¿Qué haces en la plataforma?</th></tr></thead><tbody><tr><td><strong>Planificar</strong></td><td>Cargar la matriz de riesgos, la política, los procedimientos y los documentos base.</td></tr><tr><td><strong>Hacer</strong></td><td>Ejecutar capacitaciones, entregar EPP y registrar las actividades.</td></tr><tr><td><strong>Verificar</strong></td><td>Auditar, inspeccionar y dar seguimiento a indicadores e incidentes.</td></tr><tr><td><strong>Actuar</strong></td><td>Aplicar medidas correctivas y actualizar matrices y procedimientos.</td></tr></tbody></table><p>Una obra avanza <strong>a la vez</strong> en su etapa física (qué se construye) y en su ciclo de gestión (cómo se gestiona la prevención). Ambas quedan registradas en el módulo de <a href="/manual/modulos/obras.html">Obras</a>.</p><div class="info custom-block"><p class="custom-block-title">Configuración por empresa</p><p>Qué etapas y documentos aplican a una obra puede variar según la configuración de tu empresa. Cada empresa puede personalizar qué se exige en cada etapa. Ver <a href="/manual/modulos/tenants.html">Mi Empresa</a>.</p></div><h2 id="preguntas-frecuentes" tabindex="-1">Preguntas frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas frecuentes&quot;">​</a></h2><p><strong>¿La etapa física y el ciclo de mejora son lo mismo?</strong> No. La <strong>etapa física</strong> es el avance constructivo (excavación, obra gruesa…). El <strong>ciclo de mejora</strong> (Planificar–Hacer–Verificar–Actuar) es cómo se gestiona la seguridad. Una obra avanza en ambas dimensiones a la vez.</p><p><strong>¿Por qué no me deja avanzar de etapa?</strong> Porque faltan documentos obligatorios firmados en la etapa actual. Complétalos en la pestaña <strong>DS44 — Cumplimiento</strong> de la obra y vuelve a intentar.</p><p><strong>¿Puedo volver a una etapa anterior?</strong> El avance de etapa está pensado para ir hacia adelante a medida que progresa la obra. Si necesitas corregir algo, contacta a un administrador.</p>`,19)])])}const m=e(o,[["render",n]]);export{g as __pageData,m as default};
